import Link from "next/link";
export default async function Login({searchParams}:{searchParams:Promise<{error?:string,message?:string}>}){const q=await searchParams;return <main><div className="container"><div className="formCard" style={{maxWidth:520}}><span className="eyebrow">Vendor portal</span><h1>Welcome back.</h1>{q.error&&<div className="notice error">{q.error}</div>}{q.message&&<div className="notice success">{q.message}</div>}<form action="/api/auth/login" method="post"><div className="field"><label>Email</label><input name="email" type="email" required/></div><div className="field"><label>Password</label><input name="password" type="password" required/></div><button className="btn primary" style={{width:"100%",marginTop:18}}>Sign In</button></form><div className="authLinks"><Link href="/vendor/forgot-password">Forgot password?</Link><Link href="/vendor/signup">Create a vendor account</Link></div></div></div></main>}
